import React, { useState, useEffect, useMemo } from 'react';
import './WeatherHomepage.css';
import { useNavigate } from 'react-router-dom';
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid } from 'recharts';


// --- API CONFIGURATION ---
const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

// --- ARG (Automatic Rain Gauge) CONFIGURATION ---
const ARG_STATION_ID = 'ARGS1';
// Minutes to add to the logger timestamp before display.
// 0 = show as recorded. Set to 330 if the logger clock is UTC and you want IST.
const ARG_TIME_OFFSET_MIN = 0;

const formatArgTime = (ts, withDate = true) => {
  if (!ts) return '--';
  const d = new Date(ts);
  if (isNaN(d)) return ts;
  d.setMinutes(d.getMinutes() + ARG_TIME_OFFSET_MIN);
  const time = d.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', hour12: false });
  if (!withDate) return time;
  const date = d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short' });
  return `${date}, ${time}`;
};

// Temperature at -39 °C with 0% humidity means the T/RH sensor is not connected
const isArgSensorFault = (row) =>
  row && row.temperature !== null && row.temperature <= -39;

const formatArgValue = (value, unit) =>
  value === null || value === undefined ? '--' : `${value}${unit}`;

const WeatherHomepage = ({ onNavigateToWeather }) => {
  const navigate = useNavigate();
  const [currentWeather, setCurrentWeather] = useState(null);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [historicalData, setHistoricalData] = useState([]);
  const [historicalLoading, setHistoricalLoading] = useState(false);
  const [historicalError, setHistoricalError] = useState(null);
  const [selectedDays, setSelectedDays] = useState(3);
  const [selectedMetric, setSelectedMetric] = useState('temperature');
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // ARG rainfall station state
  const [argData, setArgData] = useState([]);
  const [argLatest, setArgLatest] = useState(null);
  const [argLoading, setArgLoading] = useState(false);
  const [argError, setArgError] = useState(null);
  const [argMetric, setArgMetric] = useState('rainfall');

  // Update time every second
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // Fetch current weather data
  useEffect(() => {
    const fetchWeatherData = async () => {
      try {
        // Pointing to your Backend URL
        
        // Added '/weather' to the path
        // MATCHES BACKEND: /api/weather/current
        // MATCHES BACKEND: /api/weather/historical-data
        // Removed the query parameter completely
        const response = await fetch(`${API_BASE_URL}/api/weather/current`);
        if (response.ok) {
          const data = await response.json();
          setCurrentWeather(data);
        }
      } catch (error) {
        console.error('Error fetching weather data:', error);
      }
    };

    fetchWeatherData();
    const interval = setInterval(fetchWeatherData, 300000); // Refresh every 5 minutes
    return () => clearInterval(interval);
  }, []);
  
  const fetchHistoricalData = async (daysToFetch = selectedDays) => {
    setHistoricalLoading(true);
    setHistoricalError(null);

    try {
      const response = await fetch(`${API_BASE_URL}/api/weather/historical-data?days=${daysToFetch}&station_id=weather-v2`);
      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.error || 'Failed to fetch historical weather data');
      }

      setHistoricalData(result.data || []);
    } catch (error) {
      console.error('Error fetching historical weather data:', error);
      setHistoricalError(error.message || 'Failed to load historical data');
      setHistoricalData([]);
    } finally {
      setHistoricalLoading(false);
    }
  };

  useEffect(() => {
    fetchHistoricalData(selectedDays);
  }, [selectedDays]);

  // Fetch ARG rainfall data (from S3 via backend)
  useEffect(() => {
    const fetchArgData = async () => {
      setArgLoading(true);
      try {
        const response = await fetch(`${API_BASE_URL}/api/weather/arg-rainfall?station=${ARG_STATION_ID}&limit=96`);
        const result = await response.json();
        if (!response.ok) {
          throw new Error(result.error || 'Failed to fetch ARG data');
        }
        setArgData(result.data || []);
        setArgLatest(result.latest || null);
        setArgError(null);
      } catch (error) {
        console.error('Error fetching ARG data:', error);
        setArgError(error.message || 'Failed to load ARG data');
      } finally {
        setArgLoading(false);
      }
    };

    fetchArgData();
    const interval = setInterval(fetchArgData, 300000); // Refresh every 5 minutes
    return () => clearInterval(interval);
  }, []);

  const argChartData = useMemo(
    () => argData.map(row => ({ ...row, label: formatArgTime(row.timestamp) })),
    [argData]
  );

  const argMetricOptions = [
    { value: 'rainfall', label: 'Rainfall (mm)', color: '#0284c7' },
    { value: 'temperature', label: 'Temperature (°C)', color: '#ea580c' },
    { value: 'humidity', label: 'Humidity (%)', color: '#059669' }
  ];
  const activeArgMetric = argMetricOptions.find(m => m.value === argMetric);
  const argFault = isArgSensorFault(argLatest);

  const chartData = useMemo(() => {
    if (!historicalData || historicalData.length === 0) return [];
    const TARGET_POINTS = 30;
    const step = Math.max(1, Math.ceil(historicalData.length / TARGET_POINTS));
    return historicalData.filter((_, index) => index % step === 0);
  }, [historicalData]);

  const metricOptions = [
    { value: 'temperature', label: 'Temperature (°C)' },
    { value: 'humidity', label: 'Humidity (%)' },
    { value: 'rainfall1h', label: 'Rainfall 1h (mm)' },
    { value: 'rainfall24h', label: 'Rainfall 24h (mm)' }
  ];

  const handleAccessWeatherApp = () => {
    navigate('/weather-map');
  };

  const handleOpenRiverDashboard = () => {
    navigate('/river-forecast');
  };

  

  const handleDataRequest = () => {
    navigate('/weather-map', { state: { openTab: 'request' } });
  }
  //const handleOpenRiverDashboard = () => {
    // This will open your river forecast dashboard (running on port 8000) in a new tab.
   // window.open('http://localhost:8000', '_blank');
  //};
  
const handleOpenDemandForecasting = () => {
  navigate('/demand-forecasting');
};
  return (
    <div className="weather-homepage-container">
      {/* Government Header */}
      <header className="gov-header">
        <div className="header-top">
          <div className="header-top-content">
            <div className="gov-links">
              {/* <a href="https://www.india.gov.in" target="_blank" rel="noopener noreferrer">
                Govt.of India
              </a> */}
              {/* <a href="https://moes.gov.in" target="_blank" rel="noopener noreferrer">
                Ministry of Earth Sciences
              </a> */}
            </div>
            <div className="header-time">
              {currentTime.toLocaleString('en-IN', {
                timeZone: 'Asia/Kolkata',
                dateStyle: 'medium',
                timeStyle: 'short'
              })}
            </div>
          </div>
        </div>

        <div className="header-main">
          <div className="header-container">
            <div className="logo-section">
              <div className="logo">
                <i className="fas fa-cloud-sun"></i>
              </div>
              <div className="title-section">
                <h1>Weather Monitoring System</h1>
                <p>Adi Shankara Institute of Engineering & Technology</p>
                <div className="subtitle">Kalady, Kerala - 683574</div>
              </div>
            </div>

            <div className="header-actions">
  <button 
    className="btn btn-primary"
    onClick={handleAccessWeatherApp}
  >
    <i className="fas fa-tachometer-alt"></i>
    Access Live Data
  </button>
  <button 
    className="btn btn-success"
    onClick={handleOpenRiverDashboard}
  >
    <i className="fas fa-water"></i>
    Periyar River Forecast
  </button>
  
  {/* --- NEWLY ADDED WATER DEMAND REDIRECT BUTTON --- */}
  <button 
    className="btn btn-info"
    style={{ backgroundColor: '#0284c7', color: '#ffffff', border: 'none' }}
    onClick={handleOpenDemandForecasting}
  >
    <i className="fas fa-chart-pie" style={{ marginRight: '8px' }}></i>
    Water Demand Forecast
  </button>

  <button
    className="btn btn-arg"
    onClick={() => navigate('/arg-monitoring')}
  >
    <i className="fas fa-cloud-rain"></i>
    ARG Live Monitoring
  </button>

  <button
    className="btn btn-secondary"
    onClick={handleDataRequest}
  >
    <i className="fas fa-download"></i>
    Request Historical Data
  </button>
</div>
          </div>
        </div>
      </header>

      {/* Navigation */}
      {/* Navigation */}
<nav className="nav-bar">
  <div className="nav-container">

    {/* Mobile Menu Button */}
    <div 
      className="mobile-menu-btn"
      onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
    >
      <i className={mobileMenuOpen ? "fas fa-times" : "fas fa-bars"}></i>
    </div>

    <ul className={`nav-menu ${mobileMenuOpen ? 'active' : ''}`}>
      <li className="nav-item">
        <a href="/" className="nav-link active">Home</a>
      </li>

      <li className="nav-item">
        <a href="#arg-rainfall" className="nav-link" onClick={() => setMobileMenuOpen(false)}>
          Rainfall (ARG)
        </a>
      </li>

      <li className="nav-item">
        <a href="#about" className="nav-link">About</a>
      </li>

      <li className="nav-item">
        <a href="#services" className="nav-link">Services</a>
      </li>

      <li className="nav-item">
        <a href="#contact" className="nav-link">Contact</a>
      </li>
    </ul>

  </div>
</nav>

      {/* Hero Section */}
      <section id="home" className="hero-section">
        <div className="hero-container">
          <div className="hero-content">
            <h2>Meteorological Research & Data Center</h2>
            <p>
              Real-time meteorological data collection and analysis for research, 
              education, and public service in the Kalady region
            </p>


            <div className="hero-stats">
              <div className="stat-card">
                <span className="stat-number">24/7</span>
                <span className="stat-label">Continuous Monitoring</span>
              </div>
              <div className="stat-card">
                <span className="stat-number">
                  {currentWeather ? `${currentWeather.temperature}°C` : '--°C'}
                </span>
                <span className="stat-label">Current Temperature</span>
              </div>
              <div className="stat-card">
                <span className="stat-number">
                  {currentWeather ? `${currentWeather.humidity}%` : '--%'}
                </span>
                <span className="stat-label">Current Humidity</span>
              </div>
              
            </div>

            <div className="hero-actions">
              <button 
                className="btn btn-primary btn-large"
                onClick={handleAccessWeatherApp}
              >
                <i className="fas fa-chart-line"></i>
                View Live Weather Dashboard
              </button>
              <a href="#about" className="btn btn-outline">
                <i className="fas fa-info-circle"></i>
                Learn More
              </a>
            </div>
          </div>
        </div>
      </section>

      {/* ARG Rainfall Data Section */}
      <section id="arg-rainfall" className="arg-section">
        <div className="arg-container">
          <div className="section-header">
            <h2>Rainfall Data (ARG)</h2>
            <p>Automatic Rain Gauge station {ARG_STATION_ID}: rainfall, temperature and humidity</p>
          </div>

          {argLoading && !argLatest ? (
            <div className="arg-message">Loading ARG data...</div>
          ) : argError && !argLatest ? (
            <div className="arg-message arg-error">
              <i className="fas fa-exclamation-triangle"></i> {argError}
            </div>
          ) : argLatest ? (
            <>
              <div className="arg-cards">
                <div className="arg-card">
                  <div className="arg-card-icon arg-rain"><i className="fas fa-cloud-rain"></i></div>
                  <div className="arg-card-label">Rainfall</div>
                  <div className="arg-card-value">{formatArgValue(argLatest.rainfall, ' mm')}</div>
                </div>
                <div className="arg-card">
                  <div className="arg-card-icon arg-temp"><i className="fas fa-thermometer-half"></i></div>
                  <div className="arg-card-label">Temperature</div>
                  <div className="arg-card-value">
                    {argFault ? <span className="arg-fault">Sensor error</span> : formatArgValue(argLatest.temperature, ' °C')}
                  </div>
                </div>
                <div className="arg-card">
                  <div className="arg-card-icon arg-hum"><i className="fas fa-tint"></i></div>
                  <div className="arg-card-label">Humidity</div>
                  <div className="arg-card-value">
                    {argFault ? <span className="arg-fault">Sensor error</span> : formatArgValue(argLatest.humidity, ' %')}
                  </div>
                </div>
                <div className="arg-card">
                  <div className="arg-card-icon arg-time"><i className="fas fa-clock"></i></div>
                  <div className="arg-card-label">Last Update</div>
                  <div className="arg-card-value arg-card-small">{formatArgTime(argLatest.timestamp)}</div>
                </div>
              </div>

              <div className="arg-chart-card">
                <div className="arg-chart-header">
                  <h3>Recent Readings</h3>
                  <div className="arg-tabs">
                    {argMetricOptions.map(option => (
                      <button
                        key={option.value}
                        className={`arg-tab ${argMetric === option.value ? 'active' : ''}`}
                        onClick={() => setArgMetric(option.value)}
                      >
                        {option.label}
                      </button>
                    ))}
                  </div>
                </div>

                <ResponsiveContainer width="100%" height={280}>
                  <BarChart data={argChartData} margin={{ top: 10, right: 20, left: 0, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="label" fontSize={11} stroke="#666" minTickGap={30} />
                    <YAxis stroke="#666" fontSize={11} />
                    <Tooltip />
                    <Bar dataKey={argMetric} name={activeArgMetric.label} fill={activeArgMetric.color} />
                  </BarChart>
                </ResponsiveContainer>
              </div>

              <div className="arg-table-card">
                <h3>Latest 10 Readings</h3>
                <div className="arg-table-wrap">
                  <table className="arg-table">
                    <thead>
                      <tr>
                        <th>Time</th>
                        <th>Rainfall (mm)</th>
                        <th>Temperature (°C)</th>
                        <th>Humidity (%)</th>
                      </tr>
                    </thead>
                    <tbody>
                      {[...argData].reverse().slice(0, 10).map(row => (
                        <tr key={row.timestamp}>
                          <td>{formatArgTime(row.timestamp)}</td>
                          <td>{formatArgValue(row.rainfall, '')}</td>
                          <td>{isArgSensorFault(row) ? <span className="arg-fault">Error</span> : formatArgValue(row.temperature, '')}</td>
                          <td>{isArgSensorFault(row) ? <span className="arg-fault">Error</span> : formatArgValue(row.humidity, '')}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </>
          ) : (
            <div className="arg-message">No ARG data available yet.</div>
          )}
        </div>
      </section>

      {/* Historical Chart Section */}
      {/* <section id="historical" className="historical-section">
        <div className="historical-container">
          <div className="section-header">
            <h2>Historical Weather Trend</h2>
            <p>Live historical charting using existing weather_monitoring API data.</p>
          </div>

          <div className="historical-controls">
            <div className="control-group">
              <label>Period</label>
              <select
                value={selectedDays}
                onChange={(e) => setSelectedDays(Number(e.target.value))}
              >
                <option value={1}>Last 24 Hours</option>
                <option value={3}>Last 3 Days</option>
                <option value={7}>Last 7 Days</option>
                <option value={30}>Last 30 Days</option>
              </select>
            </div>

            <div className="control-group">
              <label>Metric</label>
              <select
                value={selectedMetric}
                onChange={(e) => setSelectedMetric(e.target.value)}
              >
                {metricOptions.map(option => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div className="chart-card">
            {historicalLoading ? (
              <div className="chart-loading">Loading historical chart...</div>
            ) : historicalError ? (
              <div className="chart-error">{historicalError}</div>
            ) : !chartData.length ? (
              <div className="chart-no-data">No historical data available for the selected period.</div>
            ) : (
              <ResponsiveContainer width="100%" height={280}>
                <BarChart data={chartData} margin={{ top: 10, right: 20, left: 0, bottom: 5 }}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} />
                  <XAxis
                    dataKey="timestamp"
                    tickFormatter={timestamp => new Date(timestamp).toLocaleDateString([], { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' })}
                    fontSize={11}
                    stroke="#666"
                    minTickGap={20}
                  />
                  <YAxis stroke="#666" fontSize={11} />
                  <Tooltip labelFormatter={label => new Date(label).toLocaleString()} />
                  <Bar dataKey={selectedMetric} fill="#3b82f6" />
                </BarChart>
              </ResponsiveContainer>
            )}

            {chartData.length > 0 && (
              <div className="chart-footer">
                Showing {chartData.length} points from {historicalData.length} raw records.
              </div>
            )}
          </div>
        </div>
      </section> */}

      {/* Features Section */}
      <section id="about" className="features-section">
        <div className="features-container">
          <div className="section-header">
            <h2>Advanced Meteorological Capabilities</h2>
            <p>
              Our advanced weather monitoring system provides reliable atmospheric insights for innovation, learning, and community benefit
            </p>
          </div>

          <div className="features-grid">
            <div className="feature-card">
              <div className="feature-icon">
                <i className="fas fa-thermometer-half"></i>
              </div>
              <h3>Real-time Monitoring</h3>
              <p>
                Continuous monitoring of temperature, humidity, pressure, wind speed, 
                wind direction, and precipitation with high-precision sensors
              </p>
            </div>

            <div className="feature-card">
              <div className="feature-icon">
                <i className="fas fa-database"></i>
              </div>
              <h3>Historical Data Archive</h3>
              <p>
                Comprehensive database of weather patterns and trends spanning multiple years, 
                available for research and analysis purposes
              </p>
            </div>

            <div className="feature-card">
              <div className="feature-icon">
                <i className="fas fa-chart-area"></i>
              </div>
              <h3>Data Analytics</h3>
              <p>
                Advanced data processing and visualization tools for climate research, 
                agricultural planning, and environmental studies
              </p>
            </div>

            <div className="feature-card">
              <div className="feature-icon">
                <i className="fas fa-graduation-cap"></i>
              </div>
              <h3>Educational Resources</h3>
              <p>
                Supporting academic research and education in meteorology, 
                environmental science, and climate studies
              </p>
            </div>

            

            <div className="feature-card">
              <div className="feature-icon">
                <i className="fas fa-shield-alt"></i>
              </div>
              <h3>Data Security</h3>
              <p>
                Secure data transmission and storage with regular backups, 
                ensuring data integrity and availability
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* Services Section */}
      <section id="services" className="services-section">
        <div className="services-container">
          <div className="section-header">
            <h2>Our Services</h2>
            <p>Comprehensive weather monitoring and data services for various applications</p>
          </div>

          <div className="services-grid">
            <div className="service-card">
              <h4>
                <i className="fas fa-eye"></i>
                Live Weather Monitoring
              </h4>
              <p>
                Real-time access to current weather conditions with automatic updates 
                every 30 seconds for immediate weather awareness
              </p>
            </div>

            <div className="service-card">
              <h4>
                <i className="fas fa-history"></i>
                Historical Data Access
              </h4>
              <p>
                Request and download historical weather data for research, 
                analysis, and academic projects with admin approval process
              </p>
            </div>

            <div className="service-card">
              <h4>
                <i className="fas fa-chart-line"></i>
                Climate Analysis
              </h4>
              <p>
                Long-term climate pattern analysis and trend identification 
                for environmental and agricultural research applications
              </p>
            </div>

            
          </div>
        </div>
      </section>

      {/* Contact Section */}
      <section id="contact" className="contact-section">
        <div className="contact-container">
          <div className="section-header">
            <h2>Contact Information</h2>
            <p>Get in touch with our weather monitoring team</p>
          </div>

          <div className="contact-grid">
            <div className="contact-info">
              <h3>Weather Station Contact</h3>
              
              <div className="contact-item">
                <div className="contact-icon">
                  <i className="fas fa-map-marker-alt"></i>
                </div>
                <div className="contact-details">
                  <h4>Address</h4>
                  <p>
                   Adi Shankara Institute of Engineering & Technology<br />
                    Kalady, Ernakulam District<br />
                    Kerala - 683574, India
                  </p>
                </div>
              </div>

              <div className="contact-item">
                <div className="contact-icon">
                  <i className="fas fa-phone"></i>
                </div>
                <div className="contact-details">
                  <h4>Phone</h4>
                  <p>+91 9846900310</p>
                </div>
              </div>

              <div className="contact-item">
                <div className="contact-icon">
                  <i className="fas fa-envelope"></i>
                </div>
                <div className="contact-details">
                  <h4>Email</h4>
                  <p>weather@adishankara.ac.in</p>
                </div>
              </div>
            </div>

            <div className="quick-access">
              <h3>Quick Access</h3>
              <div className="quick-links">
                <button 
                  className="quick-link"
                  onClick={handleAccessWeatherApp}
                >
                  <i className="fas fa-tachometer-alt"></i>
                  <span>Live Weather Dashboard</span>
                </button>

                <button 
                  className="quick-link"
                  onClick={handleDataRequest}
                >
                  <i className="fas fa-download"></i>
                  <span>Request Historical Data</span>
                </button>

                
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="footer">
        <div className="footer-container">
          <div className="footer-grid">
            <div className="footer-section">
              <h4>Weather Monitoring System</h4>
              <p>
                Advanced meteorological monitoring facility providing real-time weather data
                and historical records for research, education, and public service.
              </p>
            </div>

            <div className="footer-section">
              <h4>Quick Links</h4>
              <ul className="footer-links">
                <li><a href="#home">Home</a></li>
                <li><a href="#about">About System</a></li>
                <li><a href="#services">Services</a></li>
                <li><a href="#contact">Contact</a></li>
              </ul>
            </div>

            <div className="footer-section">
              <h4>Institution</h4>
              <ul className="footer-links">
                <li>
                  <a href="https://www.adishankara.ac.in" target="_blank" rel="noopener noreferrer">
                    Adi Shankara Institute of Engineering & Technology, Kalady
                  </a>
                </li>
              </ul>
            </div>
          </div>

          <div className="footer-bottom">
            <p>© {new Date().getFullYear()} Adi Shankara Institute of Engineering & Technology Weather Monitoring System. All rights reserved.</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default WeatherHomepage;
